  // the TOC byte rule holds for any audio codec. Video is not: the right clear
  // header and whether to escape both depend on the codec, so it fails closed.
  const DEFAULT_PROFILE = {
    rbsp: false,
    audioOnly: true,
    clearBytes: defaultClearBytes,
  };
  // Object.hasOwn, not `in`: `in` walks the prototype chain, so a codec named
  // like an Object.prototype member ('toString') would resolve to a function
  // instead of a profile.
  const getCodecProfile = (codec) =>
    codec !== undefined && Object.hasOwn(CODEC_PROFILES, codec)
      ? CODEC_PROFILES[codec]
      : DEFAULT_PROFILE;
  const isSupportedCodec = (codec) =>
    codec === undefined || Object.hasOwn(CODEC_PROFILES, codec);

  let tail = Promise.resolve();
  /**
   * Run tasks FIFO, one at a time, so a `setKey` cannot race transform setup.
   * `tail` swallows errors so one rejection cannot stall the queue; the returned
   * promise still carries that task's own outcome.
   */
  const enqueue = (fn) => {
    const run = tail.then(fn);
    tail = run.catch(() => {});
    return run;
  };

  /** Marks an encrypted frame's trailer. */
  const MAGIC = 0xe2eefeed;
  /**
   * Wire format version. Bump it when the trailer layout or IV derivation change.
   *
   * v1: [4B frameCounter][8B ivPrefix][1B keyIndex][2B clearBytes|flags]
   * [1B version][4B magic]. IV = ivPrefix ∥ frameCounter.
   */
  const E2EE_VERSION = 1;
  const IV_PREFIX_LEN = 8;
  const FRAME_COUNTER_LEN = 4;
  const IV_LEN = IV_PREFIX_LEN + FRAME_COUNTER_LEN;
  const KEY_INDEX_LEN = 1;
  const CLEAR_BYTES_LEN = 2;
  const VERSION_LEN = 1;
  const MAGIC_LEN = 4;
  /** 4 + 8 + 1 + 2 + 1 + 4 */
  const TRAILER_LEN =
    FRAME_COUNTER_LEN +
    IV_PREFIX_LEN +
    KEY_INDEX_LEN +
    CLEAR_BYTES_LEN +
    VERSION_LEN +
    MAGIC_LEN;
  /** Bit 15 of the clearBytes field. Signals RBSP escaping. */
  const RBSP_FLAG = 0x8000;
